parameters.jsCode:
const scan = $json;
const now = new Date().toISOString();
const items = [];

const results = Array.isArray(scan.results) ? scan.results : [];
for (const r of results) {
  if (r.status === 'indexed') {
    items.push({
      json: {
        should_emit: true,
        source: 'rag_ingestion',
        severity: 'info',
        component: 'knowledge',
        event: 'document_indexed',
        status: 'completed',
        timestamp: now,
        message: 'Documento indexado no RAG.',
        requires_attention: false,
        suggested_action: null,
        details: {
          document_id: r.document_id ?? null,
          filename: r.filename ?? null,
          extension: r.extension ?? null,
          chunks: r.chunks ?? null,
          content_hash: r.content_hash ?? null,
          elapsed_ms: r.elapsed_ms ?? null,
          // NÃO incluir conteúdo/chunks/texto/embedding
        },
        scan_summary: {
          scanned: scan.scanned,
          indexed: scan.indexed,
          skipped: scan.skipped,
          errors: (scan.errors || []).length,
        },
      },
    });
  } else if (r.status === 'unsupported' || r.status === 'error') {
    const sev = r.status === 'unsupported' || r.reason === 'no_text' ? 'warning' : 'error';
    items.push({
      json: {
        should_emit: true,
        source: 'rag_ingestion',
        severity: sev,
        component: 'knowledge',
        event: r.status === 'unsupported' ? 'document_unsupported' : 'document_ingest_error',
        status: 'failed',
        timestamp: now,
        message: r.status === 'unsupported'
          ? 'Documento não suportado ou sem texto extraível.'
          : 'Falha ao indexar documento no RAG.',
        requires_attention: sev === 'error',
        suggested_action: null,
        details: {
          filename: r.filename ?? null,
          extension: r.extension ?? null,
          reason: r.reason ?? null,
          status: r.status,
        },
      },
    });
  }
}

// Sem indexed/erro relevante: emitir item silencioso para não quebrar fluxo
if (!items.length) {
  items.push({
    json: {
      should_emit: false,
      source: 'rag_ingestion',
      scan_summary: {
        scanned: scan.scanned ?? 0,
        indexed: scan.indexed ?? 0,
        skipped: scan.skipped ?? 0,
        errors: (scan.errors || []).length,
      },
    },
  });
}

return items;

